import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Button } from '@/components/ui/Button.js';
import { Icon } from '@/components/ui/Icon.js';
import { Spinner } from '@/components/ui/Spinner.js';
import { promo as promoApi } from '@/api/endpoints.js';
import { ApiError, isApiError } from '@/api/errors.js';
import { useAuth } from '@/features/auth/session.js';
import { useSync } from '@/sync/store.js';
import { t } from '@/i18n/index.js';
import { safeExternalUrl } from '@/lib/externalLinks.js';
import { longDate } from '@/lib/format.js';
import type { ApiPromoOffer } from '@/api/types.js';
import styles from './Promo.module.css';

/**
 * A promotion code, typed or arrived at by a link.
 *
 * Like a shared notebook, this works with no account: an influencer's link
 * is followed by people who have never heard of Lexpad, and a page that
 * cannot say what it is offering until you sign in is a page nobody
 * finishes. What it will not do is decide for them — signing in happens
 * because they tapped the button, and the code is used on a second tap.
 *
 * A code that is real but closed says so plainly rather than pretending it
 * never existed. Somebody who wrote a code off a slide deserves to know
 * they were a week late.
 */

type State =
  | { kind: 'asking' }
  | { kind: 'looking' }
  /** The lookup failed; `message` says whether the code is unknown or the check did not happen. */
  | { kind: 'unknown'; message: string }
  | { kind: 'offer'; offer: ApiPromoOffer }
  | { kind: 'done'; until?: string };

export function Promo(): React.JSX.Element {
  const { code: fromLink } = useParams();
  const navigate = useNavigate();
  const signedIn = useAuth((state) => state.status) === 'ready';
  const [typed, setTyped] = useState(fromLink ?? '');
  const [state, setState] = useState<State>(
    fromLink === undefined ? { kind: 'asking' } : { kind: 'looking' },
  );
  const [busy, setBusy] = useState(false);
  const [failed, setFailed] = useState('');

  // A code in the address is looked up once, on arrival. A code somebody
  // types is looked up when they ask for it, which is why this effect
  // watches the link rather than the field.
  useEffect(() => {
    if (fromLink === undefined) return;
    let live = true;
    promoApi
      .look(fromLink)
      .then((offer) => {
        if (live) setState({ kind: 'offer', offer });
      })
      .catch((cause: unknown) => {
        if (live) setState({ kind: 'unknown', message: lookMessage(cause) });
      });
    return () => {
      live = false;
    };
  }, [fromLink]);

  const look = (): void => {
    const code = typed.trim();
    if (code === '') return;
    setState({ kind: 'looking' });
    setFailed('');
    promoApi
      .look(code)
      .then((offer) => {
        setState({ kind: 'offer', offer });
      })
      .catch((cause: unknown) => {
        setState({ kind: 'unknown', message: lookMessage(cause) });
      });
  };

  const use = (offer: ApiPromoOffer): void => {
    // Somebody with no account is sent to sign in and brought back here,
    // rather than having the code spent against an account that does not
    // exist yet. Using it stays their own deliberate tap.
    if (!signedIn) {
      void navigate('/auth', { state: { from: `/promo/${offer.code}` } });
      return;
    }
    setBusy(true);
    setFailed('');
    promoApi
      .redeem(offer.code)
      .then(async (got) => {
        if (got.checkoutUrl !== undefined) {
          // A checkout code has no Pro to give yet: the seller collects
          // the card and charges when the free period ends. The address is
          // typed in by an operator, so it goes only to a host on the list.
          const checkout = safeExternalUrl(got.checkoutUrl, 'checkout');
          if (checkout === undefined) {
            setBusy(false);
            setFailed(t('promo.failed'));
            return;
          }
          window.location.assign(checkout.href);
          return;
        }
        // The plan is the one thing the app reads from the network rather
        // than from this device, so it has to be pulled before Settings
        // and the AI screen will agree that anything changed.
        await useSync.getState().syncNow();
        setState(got.until === undefined ? { kind: 'done' } : { kind: 'done', until: got.until });
      })
      .catch((cause: unknown) => {
        setBusy(false);
        setFailed(redeemMessage(cause));
      });
  };

  if (state.kind === 'looking') {
    return (
      <main className={styles.screen}>
        <div className={styles.centre}>
          <Spinner />
          <p className={styles.note}>{t('promo.looking')}</p>
        </div>
      </main>
    );
  }

  if (state.kind === 'done') {
    return (
      <main className={styles.screen}>
        <div className={styles.centre}>
          <h1 className={styles.doneTitle}>{t('promo.doneTitle')}</h1>
          {state.until !== undefined && (
            <p className={styles.note}>{t('promo.doneLine', { until: longDate(state.until) })}</p>
          )}
          <Button
            onClick={() => {
              void navigate('/', { replace: true });
            }}
          >
            {t('promo.done')}
          </Button>
        </div>
      </main>
    );
  }

  return (
    <main className={styles.screen}>
      <header className={styles.head}>
        <button
          type="button"
          className={styles.back}
          aria-label={t('action.back')}
          onClick={() => {
            void navigate(-1);
          }}
        >
          <Icon name="chevronLeft" size={20} weight={2} />
        </button>
        <h1 className={styles.title}>{t('promo.title')}</h1>
      </header>

      {state.kind === 'offer' ? (
        <>
          <section className={styles.offer}>
            <span className={styles.code}>{state.offer.code}</span>
            <h2 className={styles.offerTitle}>{offerTitle(state.offer)}</h2>
            <p className={styles.offerLine}>
              {state.offer.kind === 'grant' ? t('promo.grantLine') : t('promo.checkoutLine')}
            </p>
          </section>

          {!state.offer.eligible && <p className={styles.reason}>{reasonMessage(state.offer.reason)}</p>}
          {failed !== '' && <p className={styles.failed}>{failed}</p>}

          <div className={styles.actions}>
            {state.offer.eligible && (
              <Button
                block
                size="large"
                busy={busy}
                onClick={() => {
                  use(state.offer);
                }}
              >
                {signedIn ? (busy ? t('promo.redeeming') : t('promo.redeem')) : t('promo.signIn')}
              </Button>
            )}
            <Button
              variant="secondary"
              block
              onClick={() => {
                setState({ kind: 'asking' });
                setTyped('');
                setFailed('');
              }}
            >
              {t('promo.lead')}
            </Button>
          </div>
        </>
      ) : (
        <div className={styles.form}>
          <p className={styles.note}>{t('promo.lead')}</p>
          <input
            className={styles.input}
            value={typed}
            placeholder={t('promo.placeholder')}
            aria-label={t('promo.placeholder')}
            autoCapitalize="characters"
            autoCorrect="off"
            spellCheck={false}
            autoFocus
            onChange={(event) => {
              setTyped(event.target.value);
              if (state.kind === 'unknown') setState({ kind: 'asking' });
            }}
            onKeyDown={(event) => {
              if (event.key === 'Enter') look();
            }}
          />
          {state.kind === 'unknown' && <p className={styles.reason}>{state.message}</p>}
          <Button block size="large" disabled={typed.trim() === ''} onClick={look}>
            {t('promo.check')}
          </Button>
        </div>
      )}
    </main>
  );
}

/** What the code gives, in one line. */
function offerTitle(offer: ApiPromoOffer): string {
  if (offer.kind === 'grant' && offer.days !== undefined) {
    return t('promo.grantTitle', { days: offer.days });
  }
  return t('promo.checkoutTitle');
}

/**
 * Why a real code will not work. Each reason is its own sentence, because
 * "too late", "too many people got there first" and "this was never for
 * you" are three different pieces of news and one of them is worth acting
 * on.
 */
function reasonMessage(reason: ApiPromoOffer['reason']): string {
  switch (reason) {
    case 'expired':
      return t('promo.expired');
    case 'not_started':
      return t('promo.notStarted');
    case 'used_up':
      return t('promo.usedUp');
    case 'wrong_language':
      return t('promo.wrongLanguage');
    case 'disabled':
      return t('promo.disabled');
    case 'already_used':
      return t('promo.alreadyUsedOne');
    default:
      return t('promo.failed');
  }
}

/**
 * Why a lookup found nothing. Only a 404 means the code is not real; a
 * throttled, offline or broken lookup never checked it, and telling
 * somebody to look for a typo in a code that is right sends them hunting
 * for a mistake they did not make.
 */
function lookMessage(cause: unknown): string {
  if (isApiError(cause, 'notFound')) return t('promo.notFound');
  if (isApiError(cause, 'tooMany')) return t('promo.tooMany');
  if (isApiError(cause, 'offline')) return t('promo.lookOffline');
  return t('promo.lookFailed');
}

/** Why the redemption itself failed. */
function redeemMessage(cause: unknown): string {
  if (isApiError(cause, 'offline')) return t('error.offline');
  const code = cause instanceof ApiError ? cause.code : undefined;
  switch (code) {
    case 'promo_already_used':
      return t('promo.alreadyUsedOne');
    case 'promo_already_redeemed':
      return t('promo.alreadyRedeemed');
    case 'already_subscribed':
      return t('promo.alreadyPro');
    case 'promo_not_redeemable':
      return t('promo.notRedeemable');
    case 'promo_wrong_language':
      return t('promo.wrongLanguage');
    case 'promo_expired':
      return t('promo.expired');
    case 'promo_not_started':
      return t('promo.notStarted');
    case 'promo_used_up':
      return t('promo.usedUp');
    case 'promo_disabled':
      return t('promo.disabled');
    case 'promo_not_found':
      return t('promo.notFound');
    default:
      return t('promo.failed');
  }
}
